/**
 * Consistency tests: compare browser-side ChArUco detection and calibration
 * against Python OpenCV reference results.
 *
 * Uses Playwright to run opencv.js in a real Chromium browser, since opencv.js
 * requires a full browser environment (Canvas, WebAssembly, etc.) that jsdom
 * cannot provide.
 *
 * Run: pnpm test:consistency
 * Requires: fixtures/synthetic-01/reference.json (generated by tools/reference/calibrate_reference.py)
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { chromium, type Browser, type Page } from 'playwright';
import { createServer, type Server } from 'http';
import { readFileSync, existsSync } from 'fs';
import { join, extname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = fileURLToPath(new URL('.', import.meta.url));
const PROJECT_ROOT = join(__dirname, '..');
const FIXTURE_DIR = process.env.FIXTURE_DIR || join(PROJECT_ROOT, 'fixtures', 'synthetic-01');
const REFERENCE_PATH = join(FIXTURE_DIR, 'reference.json');
const TRUTH_PATH = join(FIXTURE_DIR, 'truth.json');
const OPENCV_PATH = join(PROJECT_ROOT, 'public', 'opencv', 'opencv-4.9.0.js');

interface ReferenceImage {
  filename: string;
  charuco_ids: number[];
  charuco_corners: Array<[number, number]>;
  num_markers: number;
  used: boolean;
  rms: number;
}

const DICT_NAME_TO_ID: Record<string, number> = {
  DICT_4X4_50: 0, DICT_4X4_100: 1, DICT_4X4_250: 2, DICT_4X4_1000: 3,
  DICT_5X5_50: 4, DICT_5X5_100: 5, DICT_5X5_250: 6, DICT_5X5_1000: 7,
  DICT_6X6_50: 8, DICT_6X6_100: 9, DICT_6X6_250: 10, DICT_6X6_1000: 11,
  DICT_7X7_50: 12, DICT_7X7_100: 13, DICT_7X7_250: 14, DICT_7X7_1000: 15,
  DICT_ARUCO_ORIGINAL: 16,
};

interface ReferenceData {
  board: {
    squares_x: number;
    squares_y: number;
    square_length: number;
    marker_length: number;
    dictionary: string;
  };
  image_size: [number, number];
  images: ReferenceImage[];
  camera_matrix: number[];
  dist_coeffs: number[];
  rms: number;
  per_image_rms: number[];
}

interface TruthData {
  camera_matrix: number[];
  dist_coeffs: number[];
  image_size: [number, number];
}

const MIME: Record<string, string> = {
  '.html': 'text/html',
  '.js': 'application/javascript',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
};

describe('Consistency with Python OpenCV', () => {
  let browser: Browser;
  let page: Page;
  let server: Server;
  let port: number;
  let reference: ReferenceData;
  let truth: TruthData | null = null;

  beforeAll(async () => {
    if (!existsSync(REFERENCE_PATH)) {
      throw new Error(
        `Reference data not found at ${REFERENCE_PATH}. Run: pnpm generate:fixtures`,
      );
    }

    reference = JSON.parse(readFileSync(REFERENCE_PATH, 'utf-8'));

    if (existsSync(TRUTH_PATH)) {
      truth = JSON.parse(readFileSync(TRUTH_PATH, 'utf-8'));
    }

    // Start a simple static file server
    server = createServer((req, res) => {
      const url = new URL(req.url!, 'http://localhost');
      let filePath: string;

      if (url.pathname === '/' || url.pathname === '/index.html') {
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(`<!DOCTYPE html><html><head></head><body><script src="/opencv.js"></script></body></html>`);
        return;
      } else if (url.pathname.startsWith('/fixtures/')) {
        filePath = join(PROJECT_ROOT, url.pathname);
      } else if (url.pathname.startsWith('/opencv/')) {
        filePath = join(PROJECT_ROOT, 'public', url.pathname);
      } else if (url.pathname === '/opencv.js') {
        filePath = OPENCV_PATH;
      } else {
        res.writeHead(404);
        res.end('Not found');
        return;
      }

      try {
        const data = readFileSync(filePath);
        const ext = extname(filePath);
        res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' });
        res.end(data);
      } catch {
        res.writeHead(404);
        res.end('Not found');
      }
    });

    await new Promise<void>((resolve) => {
      server.listen(0, '127.0.0.1', () => {
        const addr = server.address();
        port = typeof addr === 'object' && addr ? addr.port : 0;
        resolve();
      });
    });

    browser = await chromium.launch({ headless: true });
    page = await browser.newPage();

    // Navigate to our test page which loads opencv.js
    await page.goto(`http://127.0.0.1:${port}/`);
    await page.waitForFunction(() => typeof cv !== 'undefined' && typeof cv.Mat === 'function', {
      timeout: 60000,
    });
  }, 120000);

  afterAll(async () => {
    await browser?.close();
    server?.close();
  });

  it('detects the same corners as Python for each image', async () => {
    for (const refImg of reference.images) {
      const imgPath = `/fixtures/synthetic-01/${refImg.filename}`;

      const result = await page.evaluate(
        async ({ imgUrl, boardConfig }) => {
          // Load image
          const response = await fetch(imgUrl);
          const blob = await response.blob();
          const bitmap = await createImageBitmap(blob);

          const canvas = document.createElement('canvas');
          canvas.width = bitmap.width;
          canvas.height = bitmap.height;
          const ctx = canvas.getContext('2d')!;
          ctx.drawImage(bitmap, 0, 0);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

          // Create grayscale Mat
          const rgbaMat = new cv.Mat(canvas.height, canvas.width, cv.CV_8UC4);
          rgbaMat.data.set(imageData.data);
          const gray = new cv.Mat();
          cv.cvtColor(rgbaMat, gray, cv.COLOR_RGBA2GRAY);
          rgbaMat.delete();

          // Create board + detector
          const dict = cv.getPredefinedDictionary(boardConfig.dictionaryId);
          const emptyIds = new cv.Mat();
          const board = new cv.aruco_CharucoBoard(
            new cv.Size(boardConfig.squaresX, boardConfig.squaresY),
            boardConfig.squareLength,
            boardConfig.markerLength,
            dict,
            emptyIds,
          );
          emptyIds.delete();

          const charucoParams = new cv.aruco_CharucoParameters();
          const detectorParams = new cv.aruco_DetectorParameters();
          const refineParams = new cv.aruco_RefineParameters(10, 3, true);
          const detector = new cv.aruco_CharucoDetector(
            board,
            charucoParams,
            detectorParams,
            refineParams,
          );

          const charucoCorners = new cv.Mat();
          const charucoIds = new cv.Mat();
          const markerCorners = new cv.MatVector();
          const markerIds = new cv.Mat();

          detector.detectBoard(gray, charucoCorners, charucoIds, markerCorners, markerIds);

          const ids: number[] = [];
          const corners: Array<[number, number]> = [];
          for (let i = 0; i < charucoIds.rows; i++) {
            ids.push(charucoIds.intAt(i, 0));
            corners.push([charucoCorners.data32F[i * 2], charucoCorners.data32F[i * 2 + 1]]);
          }
          const markerCount = markerCorners.size();

          // Cleanup
          gray.delete();
          charucoCorners.delete();
          charucoIds.delete();
          markerCorners.delete();
          markerIds.delete();
          detector.delete();
          charucoParams.delete();
          detectorParams.delete();
          refineParams.delete();
          board.delete();

          return { ids, corners, markerCount };
        },
        {
          imgUrl: `http://127.0.0.1:${port}${imgPath}`,
          boardConfig: {
            squaresX: reference.board.squares_x,
            squaresY: reference.board.squares_y,
            squareLength: reference.board.square_length,
            markerLength: reference.board.marker_length,
            dictionaryId: DICT_NAME_TO_ID[reference.board.dictionary] ?? 0,
          },
        },
      );

      // Check corner count and IDs match exactly
      expect(
        result.ids.length,
        `Corner count mismatch for ${refImg.filename}: JS=${result.ids.length}, Python=${refImg.charuco_ids.length}`,
      ).toBe(refImg.charuco_ids.length);

      expect(
        result.ids,
        `Corner IDs mismatch for ${refImg.filename}`,
      ).toEqual(refImg.charuco_ids);

      // Check corner coordinates within tolerance
      for (let i = 0; i < result.corners.length; i++) {
        const [jx, jy] = result.corners[i];
        const [px, py] = refImg.charuco_corners[i];
        const dx = Math.abs(jx - px);
        const dy = Math.abs(jy - py);
        expect(
          dx,
          `Corner ${refImg.charuco_ids[i]} X mismatch for ${refImg.filename}: JS=${jx}, Python=${px}, diff=${dx}`,
        ).toBeLessThan(1e-3);
        expect(
          dy,
          `Corner ${refImg.charuco_ids[i]} Y mismatch for ${refImg.filename}: JS=${jy}, Python=${py}, diff=${dy}`,
        ).toBeLessThan(1e-3);
      }
    }
  }, 300000);

  it('produces matching calibration results', async () => {
    const result = await page.evaluate(
      ({ boardConfig, perImage, imageSize }) => {
        const innerX = boardConfig.squaresX - 1;
        const objPtsVec = new cv.MatVector();
        const imgPtsVec = new cv.MatVector();

        for (const img of perImage) {
          const objArr: number[] = [];
          const imgArr: number[] = [];
          for (let i = 0; i < img.charuco_ids.length; i++) {
            const id = img.charuco_ids[i];
            const col = id % innerX;
            const row = Math.floor(id / innerX);
            objArr.push((col + 1) * boardConfig.squareLength, (row + 1) * boardConfig.squareLength, 0);
            imgArr.push(img.charuco_corners[i][0], img.charuco_corners[i][1]);
          }
          const objMat = cv.matFromArray(img.charuco_ids.length, 1, cv.CV_32FC3, objArr);
          const imgMat = cv.matFromArray(img.charuco_ids.length, 1, cv.CV_32FC2, imgArr);
          objPtsVec.push_back(objMat);
          imgPtsVec.push_back(imgMat);
          objMat.delete();
          imgMat.delete();
        }

        const camMat = new cv.Mat();
        const distCoeffs = new cv.Mat();
        const rvecs = new cv.MatVector();
        const tvecs = new cv.MatVector();
        const stdDevIntr = new cv.Mat();
        const stdDevExtr = new cv.Mat();
        const perViewErr = new cv.Mat();

        const rms = cv.calibrateCameraExtended(
          objPtsVec,
          imgPtsVec,
          new cv.Size(imageSize.width, imageSize.height),
          camMat,
          distCoeffs,
          rvecs,
          tvecs,
          stdDevIntr,
          stdDevExtr,
          perViewErr,
          0,
          new cv.TermCriteria(cv.TermCriteria_COUNT + cv.TermCriteria_EPS, 100, 1e-8),
        );

        const fx = camMat.doubleAt(0, 0);
        const fy = camMat.doubleAt(1, 1);
        const cx = camMat.doubleAt(0, 2);
        const cy = camMat.doubleAt(1, 2);

        const dist: number[] = [];
        for (let i = 0; i < distCoeffs.cols; i++) {
          dist.push(distCoeffs.doubleAt(0, i));
        }

        const perImgRms: number[] = [];
        for (let i = 0; i < perViewErr.rows; i++) {
          perImgRms.push(perViewErr.doubleAt(i, 0));
        }

        camMat.delete();
        distCoeffs.delete();
        rvecs.delete();
        tvecs.delete();
        stdDevIntr.delete();
        stdDevExtr.delete();
        perViewErr.delete();
        objPtsVec.delete();
        imgPtsVec.delete();

        return { rms, fx, fy, cx, cy, dist, perImgRms };
      },
      {
        boardConfig: {
          squaresX: reference.board.squares_x,
          squaresY: reference.board.squares_y,
          squareLength: reference.board.square_length,
          markerLength: reference.board.marker_length,
          dictionaryId: reference.board.dictionary,
        },
        perImage: reference.images,
        imageSize: { width: reference.image_size[0], height: reference.image_size[1] },
      },
    );

    // Compare camera matrix: relative difference < 1e-5
    const refCM = reference.camera_matrix; // flat 3x3
    const refFx = refCM[0],
      refFy = refCM[4],
      refCx = refCM[2],
      refCy = refCM[5];

    console.log(`\nCalibration comparison:`);
    console.log(`  fx: JS=${result.fx.toFixed(6)}, Python=${refFx.toFixed(6)}, relDiff=${Math.abs(result.fx - refFx) / refFx}`);
    console.log(`  fy: JS=${result.fy.toFixed(6)}, Python=${refFy.toFixed(6)}, relDiff=${Math.abs(result.fy - refFy) / refFy}`);
    console.log(`  cx: JS=${result.cx.toFixed(6)}, Python=${refCx.toFixed(6)}, relDiff=${Math.abs(result.cx - refCx) / refCx}`);
    console.log(`  cy: JS=${result.cy.toFixed(6)}, Python=${refCy.toFixed(6)}, relDiff=${Math.abs(result.cy - refCy) / refCy}`);
    console.log(`  RMS: JS=${result.rms.toFixed(8)}, Python=${reference.rms.toFixed(8)}, diff=${Math.abs(result.rms - reference.rms)}`);

    expect(Math.abs(result.fx - refFx) / refFx, `fx relative diff too large`).toBeLessThan(1e-5);
    expect(Math.abs(result.fy - refFy) / refFy, `fy relative diff too large`).toBeLessThan(1e-5);
    expect(Math.abs(result.cx - refCx) / refCx, `cx relative diff too large`).toBeLessThan(1e-5);
    expect(Math.abs(result.cy - refCy) / refCy, `cy relative diff too large`).toBeLessThan(1e-5);

    // Distortion coefficients: absolute difference < 1e-6
    for (let i = 0; i < Math.min(result.dist.length, reference.dist_coeffs.length); i++) {
      const diff = Math.abs(result.dist[i] - reference.dist_coeffs[i]);
      console.log(`  dist[${i}]: JS=${result.dist[i].toExponential(6)}, Python=${reference.dist_coeffs[i].toExponential(6)}, diff=${diff.toExponential(3)}`);
      expect(diff, `dist[${i}] absolute diff too large: ${diff}`).toBeLessThan(1e-6);
    }

    // RMS: absolute difference < 1e-4
    expect(
      Math.abs(result.rms - reference.rms),
      `RMS diff too large: JS=${result.rms}, Python=${reference.rms}`,
    ).toBeLessThan(1e-4);

    // If truth data exists (synthetic), report comparison with ground truth
    if (truth) {
      const truthFx = truth.camera_matrix[0];
      const truthFy = truth.camera_matrix[4];
      const truthCx = truth.camera_matrix[2];
      const truthCy = truth.camera_matrix[5];

      console.log(`\nComparison with ground truth (informational, no pass/fail):`);
      console.log(`  fx: estimated=${result.fx.toFixed(2)}, truth=${truthFx}, error=${Math.abs(result.fx - truthFx).toFixed(4)}`);
      console.log(`  fy: estimated=${result.fy.toFixed(2)}, truth=${truthFy}, error=${Math.abs(result.fy - truthFy).toFixed(4)}`);
      console.log(`  cx: estimated=${result.cx.toFixed(2)}, truth=${truthCx}, error=${Math.abs(result.cx - truthCx).toFixed(4)}`);
      console.log(`  cy: estimated=${result.cy.toFixed(2)}, truth=${truthCy}, error=${Math.abs(result.cy - truthCy).toFixed(4)}`);

      for (let i = 0; i < Math.min(result.dist.length, truth.dist_coeffs.length); i++) {
        console.log(`  dist[${i}]: estimated=${result.dist[i].toExponential(4)}, truth=${truth.dist_coeffs[i].toExponential(4)}`);
      }
    }
  }, 120000);
});
